    "遇到球球海狮（<i class='jp'>Popplio</i>），从沙地开口潜下去。升到高级才能开门（要扩展票），把这里的环境等级升到 3。",
    "接 <b>「建造美丽建筑吧！」</b>：50 星斑岩、30 石头、25 贝壳、10 闪亮珍珠、10 贝壳栅栏、2 海洋门 + 15 只宝可梦。",
